SELECT COUNT(*) FROM inspect_plan_project ipp JOIN inspect_plan ip ON ipp.plan_id = ip.id JOIN project p ON ipp.project_id = p.id
AND (ip.plan_name LIKE CONCAT('%', #{keyword}, '%') OR p.project_name LIKE CONCAT('%', #{keyword}, '%'))
AND ip.status = #{status}

SELECT pp.id AS planProjectId, p.id AS planId, p.plan_name AS planName, pp.project_id AS projectId, proj.project_name AS projectName, p.start_time AS startTime, p.end_time AS endTime, p.status AS status, pp.total_count AS totalCount, pp.inspected_count AS inspectedCount FROM inspect_plan_project pp JOIN inspect_plan p ON pp.plan_id = p.id JOIN project proj ON pp.project_id = proj.id
AND (p.plan_name LIKE CONCAT('%', #{keyword}, '%') OR proj.project_name LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
ORDER BY p.end_time DESC, p.id, pp.project_id LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM inspect_plan p
AND (p.plan_name LIKE CONCAT('%', #{keyword}, '%') OR p.id IN (SELECT pp.plan_id FROM inspect_plan_project pp JOIN project proj ON pp.project_id = proj.id WHERE proj.project_name LIKE CONCAT('%', #{keyword}, '%')))
AND p.status = #{status}

SELECT p.id AS planId, p.plan_name AS planName, p.start_time AS startTime, p.end_time AS endTime, p.status AS status, p.total_count AS totalCount, p.inspected_count AS inspectedCount, (SELECT COUNT(*) FROM inspect_plan_project pp WHERE pp.plan_id = p.id) AS projectCount FROM inspect_plan p
AND (p.plan_name LIKE CONCAT('%', #{keyword}, '%') OR p.id IN (SELECT pp2.plan_id FROM inspect_plan_project pp2 JOIN project proj ON pp2.project_id = proj.id WHERE proj.project_name LIKE CONCAT('%', #{keyword}, '%')))
AND p.status = #{status}
ORDER BY p.end_time DESC, p.id DESC LIMIT #{offset}, #{limit}

SELECT pp.id AS planProjectId, pp.project_id AS projectId, pp.total_count AS totalCount, pp.inspected_count AS inspectedCount, p.id AS planId, p.plan_name AS planName, p.start_time AS startTime, p.end_time AS endTime, p.status AS status FROM inspect_plan_project pp JOIN inspect_plan p ON pp.plan_id = p.id AND p.status = 1 WHERE pp.project_id IN
#{pid}
ORDER BY pp.project_id, pp.id DESC

