UPDATE inspect_plan p
LEFT JOIN (
    SELECT plan_id, SUM(total_count) AS total_sum, SUM(inspected_count) AS inspected_sum
    FROM inspect_plan_project
    WHERE plan_id = #{id}
    GROUP BY plan_id
) pp ON p.id = pp.plan_id
SET p.total_count = COALESCE(pp.total_sum, 0),
    p.inspected_count = COALESCE(pp.inspected_sum, 0)
WHERE p.id = #{id}
